%% @doc The message modules, generated by gpb.
%%
%% gpb compiles every proto file into one module that encodes and decodes
%% its messages, with the messages of other files they use. It reads the
%% definitions from the descriptors protoc parsed, not the proto files
%% themselves, so any file protoc reads works, and each module gets only
%% the definitions its file uses: not, say, all of descriptor.proto because
%% the file imports `trevrpc/options.proto', which extends it.
%%
%% Messages are maps by default (`msg_format=maps'), or records
%% (`msg_format=records', with the record definitions in a `.hrl' file of
%% the module's name). Strings are binaries, and message names carry their
%% package, as gpb's `strings_as_binaries' and `use_packages' have them.
-module(trevrpc_gen_messages).

-export([defs/1, generate/4]).

-export_type([defs/0, format/0]).

-type defs() :: list().
-type format() :: maps | records.

%% @doc The definitions of every message, enum and service in a
%% `FileDescriptorSet'.
-spec defs(binary()) -> {ok, defs()} | {error, binary()}.
defs(FileSet) ->
    %% Version 2 represents proto3 optional fields.
    case gpb_parse_descr:defs_from_descriptors(FileSet, [use_packages, {proto_defs_version, 2}]) of
        {ok, Defs} -> {ok, Defs};
        {error, Reason} -> {error, iolist_to_binary(gpb_parse_descr:format_error(Reason))}
    end.

%% @doc The files of module `Module', which encodes and decodes the messages
%% of proto file `File' and the services' messages: `Module.erl', and
%% `Module.hrl' for records.
-spec generate(binary(), binary(), defs(), format()) ->
    {ok, [{binary(), iodata()}]} | {error, binary()}.
generate(File, Module, Defs, Format) ->
    Own = own(File, Defs),
    Needed = needed(Own, Defs),
    Self = self(),
    Ref = make_ref(),
    Write = fun(Path, Data) ->
        Self ! {Ref, filename:basename(Path), Data},
        ok
    end,
    Opts = [
        use_packages,
        strings_as_binaries,
        %% gpb specifies only some of the functions it exports.
        {erlc_compile_options, "nowarn_missing_spec"},
        %% The files go to Write, which keeps their names alone.
        {o, "."},
        {file_op, [{write_file, Write}]},
        return
        | case Format of
            maps -> [maps];
            %% Definitions as records would need gpb's header to compile.
            records -> [defs_as_proplists]
        end
    ],
    Result = gpb_compile:proto_defs(binary_to_atom(Module, utf8), keep(File, Needed, Defs), Opts),
    Files = written(Ref, []),
    case Result of
        {ok, _Warnings} ->
            {ok, [
                {unicode:characters_to_binary(Name), Data}
             || {Name, Data} <- lists:sort(Files)
            ]};
        {error, Reason, _Warnings} ->
            {error, iolist_to_binary(gpb_compile:format_error(Reason))}
    end.

written(Ref, Files) ->
    receive
        {Ref, Name, Data} -> written(Ref, [{Name, Data} | Files])
    after 0 -> Files
    end.

%% The messages and enums file `File' defines, and those its services
%% take and return. gpb names a file by its base name.
own(File, Defs) ->
    Key = gpb_key(File, Defs),
    Contained = lists:append([
        Names
     || {{Kind, K}, Names} <- Defs,
        K =:= Key,
        Kind =:= msg_containment orelse Kind =:= enum_containment
    ]),
    Services = [
        Service
     || {{service_containment, K}, Services} <- Defs, K =:= Key, Service <- Services
    ],
    Rpcs = lists:append([Rpcs || {{service, S}, Rpcs} <- Defs, lists:member(S, Services)]),
    Contained ++ lists:append([[element(3, Rpc), element(4, Rpc)] || Rpc <- Rpcs]).

gpb_key(File, Defs) ->
    hd([Key || {file, {Key, Name}} <- Defs, unicode:characters_to_binary(Name) =:= File]).

%% `Names' and the messages and enums they use, all the way down.
needed(Names, Defs) ->
    Types = maps:from_list([{Name, Fields} || {{Kind, Name}, Fields} <- Defs, type_kind(Kind)]),
    needed(Names, Types, #{}).

needed([], _Types, Seen) ->
    Seen;
needed([Name | Rest], Types, Seen) when is_map_key(Name, Seen) ->
    needed(Rest, Types, Seen);
needed([Name | Rest], Types, Seen) ->
    Used =
        case maps:find(Name, Types) of
            {ok, Fields} when is_list(Fields) -> refs(Fields);
            _ -> []
        end,
    needed(Used ++ Rest, Types, Seen#{Name => true}).

type_kind(msg) -> true;
type_kind(group) -> true;
type_kind(enum) -> true;
type_kind(_) -> false.

%% The type names a definition refers to, wherever they sit in it: in
%% fields, oneofs and maps.
refs({Kind, Name}) when (Kind =:= msg orelse Kind =:= group orelse Kind =:= enum), is_atom(Name) ->
    [Name];
refs(Term) when is_tuple(Term) ->
    refs(tuple_to_list(Term));
refs(Terms) when is_list(Terms) ->
    lists:append([refs(Term) || Term <- Terms]);
refs(_Term) ->
    [].

%% The definitions that concern the needed types, the services of `File',
%% and the files they come from, whose definitions follow their `file'
%% entries.
keep(File, Needed, Defs) ->
    Key = gpb_key(File, Defs),
    Types = maps:from_list([{Name, Kind} || {{Kind, Name}, _} <- Defs, type_kind(Kind)]),
    Files = maps:from_list(
        [{Key, true}] ++
            [
                {K, true}
             || {{Kind, K}, Names} <- Defs,
                Kind =:= msg_containment orelse Kind =:= enum_containment,
                lists:any(fun(Name) -> is_map_key(Name, Needed) end, Names)
            ]
    ),
    Services = services(Key, Defs),
    walk(
        Defs,
        #{key => Key, needed => Needed, types => Types, files => Files, services => Services},
        Key
    ).

walk([], _Context, _Current) ->
    [];
walk([{file, {K, _}} = Def | Rest], #{files := Files} = Context, _Current) ->
    [Def || is_map_key(K, Files)] ++ walk(Rest, Context, K);
walk([Def | Rest], Context, Current) ->
    case kept(Def, Context, Current) of
        true -> [Def | walk(Rest, Context, Current)];
        {true, Kept} -> [Kept | walk(Rest, Context, Current)];
        false -> walk(Rest, Context, Current)
    end.

kept({{Kind, Name}, _}, #{needed := Needed}, _Current) when
    Kind =:= msg; Kind =:= group; Kind =:= enum
->
    is_map_key(Name, Needed);
kept({proto3_msgs, Names}, #{needed := Needed}, _Current) ->
    {true, {proto3_msgs, [Name || Name <- Names, is_map_key(Name, Needed)]}};
kept({{service, _}, _} = Service, #{services := Services}, _Current) ->
    lists:member(Service, Services);
%% Entries of a file: what it contains, its package.
kept({{Kind, K}, Value}, #{files := Files} = Context, _Current) when is_list(K) ->
    case is_map_key(K, Files) of
        false -> false;
        true -> {true, {{Kind, K}, contained(Kind, K, Value, Context)}}
    end;
%% Extension ranges, reserved numbers and the like of a type.
kept({{_Kind, Name}, _}, #{types := Types, needed := Needed}, _Current) when is_atom(Name) ->
    not is_map_key(Name, Types) orelse is_map_key(Name, Needed);
%% The package, syntax and imports of the file the entry follows.
kept(_Def, #{files := Files}, Current) ->
    is_map_key(Current, Files).

contained(Kind, _K, Names, #{needed := Needed}) when
    Kind =:= msg_containment; Kind =:= enum_containment
->
    [Name || Name <- Names, is_map_key(Name, Needed)];
contained(Kind, K, Names, #{key := Key}) when
    Kind =:= service_containment; Kind =:= rpc_containment
->
    [Name || K =:= Key, Name <- Names];
contained(_Kind, _K, Value, _Context) ->
    Value.

services(Key, Defs) ->
    Names = [S || {{service_containment, K}, Services} <- Defs, K =:= Key, S <- Services],
    [Def || {{service, S}, _} = Def <- Defs, lists:member(S, Names)].
